#include <iostream>

int main() {
    int a = 10;
    int b = 20;

    // 1. Pointer to const data: data is read-only, pointer can move
    const int* pDataConst = &a;
    std::cout << "pDataConst: " << *pDataConst << "\n";
    pDataConst = &b; // OK: reassign pointer
    std::cout << "pDataConst after move: " << *pDataConst << "\n";

    // 2. Constant pointer: pointer is fixed, data can be modified
    int* const pPtrConst = &a;
    *pPtrConst = 15; // OK: modify target data
    std::cout << "a via pPtrConst: " << a << "\n";

    // 3. Const pointer to const data: neither can change
    const int* const pBoth = &b;
    std::cout << "pBoth: " << *pBoth << "\n";

    return 0;
}

#include <iostream>

int main() {
    int list[6] = {11, 12, 13, 14, 15, 16};
    int* p = list;

    for (int i = 0; i < 6; ++i) {
        // Demonstrating pointer and index equivalence
        std::cout << "idx: " << i 
                  << " val_deref: " << *(p + i) 
                  << " val_bracket: " << p[i] << "\n";
    }

    // Caution demonstration: *(list + 1) vs *list + 1
    std::cout << "*(list + 1): " << *(list + 1) << "\n";
    std::cout << "*list + 1: " << (*list + 1) << "\n";

    // Pointer comparison
    int* pFirst = &list[0];
    int* pLast = &list[5];
    if (pFirst < pLast) {
        std::cout << "pFirst points before pLast\n";
    }

    return 0;
}

#include <iostream>

// Pass pointer by value: can modify data, cannot redirect caller's pointer
void modifyValue(int* ptr) {
    *ptr = 99;
}

// Pass pointer by reference: can redirect caller's pointer
void redirectPointer(int* &ptr, int* newTarget) {
    ptr = newTarget;
}

int main() {
    // C-string inspection
    const char* city = "Dallas";
    std::cout << "city: " << city << "\n";
    std::cout << "city[0]: " << city[0] << "\n";
    std::cout << "*(city + 1): " << *(city + 1) << "\n";

    const char* cities[] = {"Dallas", "Atlanta", "Houston"};
    std::cout << "cities[0]: " << cities[0] << "\n";
    std::cout << "cities[0][0]: " << cities[0][0] << "\n";

    // Pointer parameter mechanics
    int val1 = 10;
    int val2 = 20;
    int* p = &val1;

    modifyValue(p);
    std::cout << "val1 after modifyValue: " << val1 << "\n";

    redirectPointer(p, &val2);
    std::cout << "*p after redirectPointer: " << *p << "\n";

    return 0;
}
